SCHEMA = {"vendor", "product", "supplies"}

knowledge_graph = {
    "falcon_cloud": {"type": "vendor", "aliases": ["falcon cloud", "falcon cloud services"]},
}

def resolve_entity(mention, graph):
    # entity resolution across sources
    mention_lower = mention.lower()
    for node_id, node in graph.items():
        if mention_lower in [a.lower() for a in node["aliases"]]:
            return node_id
    return None

def query_by_relationship(node_id, relationship, graph):
    # querying graph databases with structured queries
    if relationship not in SCHEMA:
        return f"Invalid relationship type: {relationship}"
    return graph.get(node_id, {}).get(relationship, "No data")

mention_a = "Falcon Cloud"
mention_b = "falcon cloud services"

resolved_a = resolve_entity(mention_a, knowledge_graph)
resolved_b = resolve_entity(mention_b, knowledge_graph)

print("Knowledge graph RAG:")
print(f"'{mention_a}' resolved to: {resolved_a}")
print(f"'{mention_b}' resolved to: {resolved_b}")
print(f"Both mentions resolve to the same node: {resolved_a == resolved_b}")
